preset_css:
/* MorBranding Manual Inject */
.main-header { border-top: 8px solid var(--accent); border-bottom: 2px solid var(--fg-base); }
.mor-post { border: 1px solid var(--border-color); border-top: 3px solid var(--fg-base); }
.mor-post::before { content: "MORIBUND INSTITUTE \00b7 BRAND FILE"; display: block; text-align: right; font-size: 10px; font-weight: 700; letter-spacing: 0.18em; color: var(--accent); margin-bottom: 6px; }
h1, h2, h3 { text-transform: uppercase; letter-spacing: 0.06em; }
.post-body { counter-reset: spec; }
.post-body h2 { counter-increment: spec; }
.post-body h2::before { content: counter(spec, decimal-leading-zero) " \2014 "; color: var(--accent); }
blockquote { border-left: 6px solid var(--accent); background: var(--bg-elevated); }
a { text-decoration-color: var(--accent); text-decoration-thickness: 2px; text-underline-offset: 2px; }
.post-body img { border: 1px solid var(--border-color); background: var(--bg-elevated); padding: 6px; }
